const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Start a transaction for both changes
const transaction = db.transaction(() => {
  // 1. Remove CI-0005 (Harbor Cotton Crew Tee - out of stock)
  db.prepare('DELETE FROM cart_items WHERE cart_item_id = ? AND cart_id = ?').run('CI-0005', 'CART-user_58b0a2d6');

  // 2. Update CI-0006 quantity from 3 to 2
  db.prepare('UPDATE cart_items SET quantity = 2 WHERE cart_item_id = ? AND cart_id = ?').run('CI-0006', 'CART-user_58b0a2d6');

  // 3. Update cart: item_ids_json and recalculate totals
  //    CI-0006: \$89 x 2 = \$178
  //    CI-0007: \$72 x 2 = \$144
  //    New subtotal/total: \$322
  const newItemIds = JSON.stringify(['CI-0006', 'CI-0007']);
  db.prepare('UPDATE carts SET item_ids_json = ?, subtotal = 322, total = 322 WHERE cart_id = ?').run(newItemIds, 'CART-user_58b0a2d6');
});

transaction();

// Verify changes
const cart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get('CART-user_58b0a2d6');
const items = db.prepare('SELECT ci.*, p.name, p.price, p.in_stock FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.cart_id = ?').all('CART-user_58b0a2d6');

console.log('=== UPDATED CART ===');
console.log('Cart ID:', cart.cart_id);
console.log('Items:', cart.item_ids_json);
console.log('Subtotal: \$' + cart.subtotal);
console.log('Shipping:', cart.shipping_option, '(\$' + cart.shipping_cost + ')');
console.log('Total: \$' + cart.total);
console.log();
items.forEach(i => {
  console.log(' ', i.cart_item_id, '|', i.name, '| Qty:', i.quantity, '| \$' + i.price + ' ea | In stock:', i.in_stock ? 'Yes' : 'No');
});
"

